  }
}

class StringInstrument { // TODO: Make StringInstrument inherit from Instrument
  // TODO: Implement constructor(name, numStrings) that calls the parent constructor

  // TODO: Implement tune() method which returns "Tuning the {name} with {numStrings} strings."

  // TODO: Override the play() method to return "${name} with ${numStrings} strings is playing a melody."
}

class Guitar { // TODO: Make Guitar inherit from StringInstrument
  // TODO: Implement constructor(name, numStrings, type) that calls the parent constructor

  // TODO: Implement strum() method which returns "Strumming the {type} {name}!"

  // TODO: Override the play() method to return "The {type} {name} with ${numStrings} strings is playing a rock anthem!"
}

// To test your code, uncomment the following lines:
// const bass = new Guitar("Bass", 4, "Electric");
// console.log(bass.play());
// console.log(bass.tune());
// console.log(bass.strum());

