hints.code_snippet:
class Instrument {
  constructor(name) {
    this.name = name;
  }

  play() {
    return `${this.name} is making a sound.`;
  }
}

class StringInstrument extends Instrument { 
  constructor(name, numStrings) {
    super(name);
    this.numStrings = numStrings;
  }

  tune() {
    return `Tuning the ${this.name} with ${this.numStrings} strings.`;
  }

  play() {
    return `${this.name} with ${this.numStrings} strings is playing a melody.`;
  }
}

class Guitar extends StringInstrument { 
  constructor(name, numStrings, type) {
    super(name, numStrings);
    this.type = type;
    this.name = name; 
  }

  strum() {
    return `Strumming the ${this.type} ${this.name}!`;
  }

  play() {
    return `The ${this.type} ${this.name} with ${this.numStrings} strings is playing a rock anthem!`;
  }
}

// To test your code, uncomment the following lines:
// const bass = new Guitar("Bass", 4, "Electric");
// console.log(bass.play());
// console.log(bass.tune());
// console.log(bass.strum());

// const violin = new StringInstrument("Violin", 4);
// console.log(violin.play());
// console.log(violin.tune());

